{"cards": [{"node_code": "N_3ef6ca1147a6ff47", "definition": "指客运索道在投入使用前及运营期间，向特种设备安全监督管理部门进行的法定登记、许可变更、注销及标识悬挂等行政合规管理活动。", "boundary": "本节点聚焦于索道作为特种设备的管理属性与行政手续。边界在于区分“行政登记”与“技术检验”：本节点处理的是使用登记证、许可变更申请等文书与流程；而设备是否具备使用条件的技术判定、定期检验报告归入检验检测与维护节点。不涉及索道的设计建造过程。", "includes": ["客运索道使用登记证的申领、变更与注销流程", "使用登记标志的悬挂规范及登记信息的公示管理", "索道运营单位主体资格变更时的登记更新手续"], "excludes": ["索道设备的定期检验、日常检查及故障维修（归入检验检测与维护）", "索道的设计、制造、安装及改造过程（归入设计与建造）"], "sibling_distinctions": [{"other_code": "N_86c67d4783b2ed90", "rule": "本节点关注索道“身份”的行政合规（登记、许可）；兄弟节点关注索道“运行”的技术规范（操作、调度）。"}, {"other_code": "N_4f68bf88ed0cceda", "rule": "本节点关注对外行政手续（登记）；兄弟节点关注内部人员资质与培训管理。"}, {"other_code": "N_7d17f1017c25e575", "rule": "本节点关注法定登记证书及变更；兄弟节点关注全生命周期技术档案的建立与保存。"}], "cross_boundary_rule": "涉及索道使用登记时，若为行政申请与证书管理，归入本节点；若涉及登记前必须完成的技术检验报告，检验部分归入检验检测与维护，登记动作归入本节点。"}, {"node_code": "N_86c67d4783b2ed90", "definition": "指客运索道在运行、停梯、应急处理及日常维护期间，操作人员必须遵循的技术标准、作业流程、安全注意事项及应急处置预案。", "boundary": "本节点聚焦于索道运行过程中的具体操作行为与技术规范。边界在于区分“操作规程”与“人员管理”：本节点规定“怎么做”（如启动顺序、限速要求、紧急制动操作）；而“谁来做”（如持证上岗、培训考核）归入人员管理节点。不涉及设备本身的机械结构原理或设计参数。", "includes": ["索道启动、运行、停梯的标准作业程序（SOP）", "恶劣天气、设备故障等突发情况下的应急处置操作规范", "日常运行中的安全巡视、限速控制及乘客上下站操作规范"], "excludes": ["索道操作人员的资质认定、培训考核及持证上岗管理（归入作业与服务人员管理）", "索道设备的定期检验、维护修理及故障排除技术（归入检验检测与维护）"], "sibling_distinctions": [{"other_code": "N_3ef6ca1147a6ff47", "rule": "本节点关注运行中的技术操作规范；兄弟节点关注使用前的行政登记手续。"}, {"other_code": "N_4f68bf88ed0cceda", "rule": "本节点规定操作行为标准；兄弟节点规定人员资质与培训要求。"}, {"other_code": "N_7d17f1017c25e575", "rule": "本节点是操作依据（规程）；兄弟节点是操作记录与设备历史的载体（档案）。"}], "cross_boundary_rule": "涉及索道操作时，若为具体动作、流程、技术参数执行，归入本节点；若为操作人员是否具备执行该操作的资格，归入人员管理。"}, {"node_code": "N_4f68bf88ed0cceda", "definition": "指客运索道运营单位对驾驶员、维修工、安全管理人员等关键岗位人员的资质审核、持证上岗、定期培训、考核及日常劳动纪律管理。", "boundary": "本节点聚焦于索道运营中“人”的管理。边界在于区分“人员管理”与“操作规程”：本节点关注人员是否具备资格、是否经过培训、是否遵守劳动纪律；而具体操作动作的技术标准归入安全操作规程节点。不涉及设备本身的技术状态或行政登记手续。", "includes": ["索道作业人员（驾驶员、维修工等）的持证上岗与资质审核", "岗位人员的定期安全教育、技能培训及考核记录管理", "运营单位安全管理人员的职责划分与日常劳动纪律监督"], "excludes": ["索道具体操作动作、流程及应急处置的技术规范（归入安全操作规程）", "索道设备的定期检验、维护修理及故障排除（归入检验检测与维护）"], "sibling_distinctions": [{"other_code": "N_3ef6ca1147a6ff47", "rule": "本节点关注内部人员资质与培训；兄弟节点关注对外行政登记手续。"}, {"other_code": "N_86c67d4783b2ed90", "rule": "本节点关注人员资格与培训（谁来做）；兄弟节点关注操作标准（怎么做）。"}, {"other_code": "N_7d17f1017c25e575", "rule": "本节点关注人员资质档案；兄弟节点关注设备全生命周期技术档案。"}], "cross_boundary_rule": "涉及索道人员时，若为资质、培训、考核、纪律，归入本节点；若为人员执行操作的具体技术动作，归入安全操作规程。"}]}
